"""Durability/migration boundaries using real SQLite and synthetic fixtures."""
from contextlib import closing
import multiprocessing
from pathlib import Path
import sqlite3
import subprocess
import sys
import tempfile
import unittest

from bookmarks.errors import ConfigurationError, StorageError
from bookmarks.service import BookmarkService


# A frozen prior schema fixture, not generated by the implementation under test.
V1_SCHEMA = """
CREATE TABLE items (
    id TEXT PRIMARY KEY NOT NULL,
    url TEXT NOT NULL UNIQUE COLLATE BINARY,
    title TEXT NOT NULL,
    revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
    enrichment_status TEXT NOT NULL DEFAULT 'not_started'
)
"""


def _concurrent_save(root, title, barrier, results):
    """Spawned interpreter; the barrier races schema initialization and save."""
    try:
        barrier.wait(timeout=15)
        item = BookmarkService(Path(root)).save_link("https://example.org/race?version=1#part", title)
        results.put(("ok", item))
    except Exception as error:
        results.put(("error", repr(error)))


class StorageTests(unittest.TestCase):
    def setUp(self):
        self.temporary = tempfile.TemporaryDirectory(prefix="bookmarks-storage-")
        self.addCleanup(self.temporary.cleanup)
        self.root = Path(self.temporary.name)
        self.database = self.root / "bookmarks.sqlite3"

    def test_import_does_not_create_files_or_resolve_profile_storage(self):
        # Fresh interpreter/cwd catches accidental module-level service creation.
        repository = str(Path(__file__).resolve().parents[1])
        code = (
            "import os, sys; sys.path.insert(0, sys.argv[1]); "
            "os.environ['HOME'] = os.getcwd(); "
            "os.environ['HERMES_HOME'] = os.getcwd(); "
            "import bookmarks, bookmarks.service, bookmarks.storage"
        )
        result = subprocess.run(
            [sys.executable, "-B", "-c", code, repository],
            cwd=self.root, capture_output=True, text=True, timeout=20,
        )
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual(list(self.root.iterdir()), [])

    def test_new_root_creates_versioned_database_only_when_constructed(self):
        nested = self.root / "installation" / "library"
        self.assertFalse(nested.exists())
        service = BookmarkService(nested)
        self.assertEqual(service.search("")["total"], 0)
        with closing(sqlite3.connect(nested / "bookmarks.sqlite3")) as connection, connection:
            self.assertEqual(connection.execute("PRAGMA user_version").fetchone()[0], 6)
            self.assertEqual(connection.execute("PRAGMA integrity_check").fetchone()[0], "ok")

    def test_upgrade_preserves_existing_id_revision_title_and_populates_fts(self):
        with closing(sqlite3.connect(self.database)) as connection, connection:
            connection.execute(V1_SCHEMA)
            connection.execute("PRAGMA user_version = 1")
            connection.execute(
                "INSERT INTO items VALUES (?, ?, ?, ?, ?)",
                ("existing-id", "https://example.org/migrated", "Migrationneedle 東京", 7, "not_started"),
            )
        service = BookmarkService(self.root)
        expected = {
            "id": "existing-id", "url": "https://example.org/migrated",
            "title": "Migrationneedle 東京", "revision": 7, "enrichment_status": "not_started",
            "summary": "", "tags": [], "enrichment_job_id": None,
        }
        item = service.get("existing-id")
        self.assertEqual({key: item[key] for key in expected}, expected)
        self.assertEqual(item['kind'], 'link')
        self.assertEqual(item['notes'], '')
        self.assertEqual(item['attachments'], [])
        self.assertEqual(service.search("Migrationneedle")["items"], [item])
        self.assertEqual(BookmarkService(self.root).search("東京")["items"], [item])

    def test_failed_migration_rolls_back_schema_and_version(self):
        with closing(sqlite3.connect(self.database)) as connection, connection:
            connection.execute("CREATE TABLE items_fts (marker TEXT)")
            connection.execute("INSERT INTO items_fts VALUES ('preserve')")
        with self.assertRaises(StorageError):
            BookmarkService(self.root)
        with closing(sqlite3.connect(self.database)) as connection, connection:
            self.assertEqual(connection.execute("PRAGMA user_version").fetchone()[0], 0)
            self.assertEqual(connection.execute("SELECT marker FROM items_fts").fetchall(), [("preserve",)])
            self.assertEqual(connection.execute(
                "SELECT name FROM sqlite_master WHERE name = 'items'"
            ).fetchall(), [])

    def test_newer_schema_is_rejected_without_downgrade_or_data_loss(self):
        with closing(sqlite3.connect(self.database)) as connection, connection:
            connection.execute("PRAGMA user_version = 999")
            connection.execute("CREATE TABLE future_data (marker TEXT)")
            connection.execute("INSERT INTO future_data VALUES ('preserve')")
        with self.assertRaises(ConfigurationError):
            BookmarkService(self.root)
        with closing(sqlite3.connect(self.database)) as connection, connection:
            self.assertEqual(connection.execute("PRAGMA user_version").fetchone()[0], 999)
            self.assertEqual(connection.execute("SELECT marker FROM future_data").fetchall(), [("preserve",)])

    def test_invalid_root_and_corrupt_database_errors_do_not_leak_paths(self):
        occupied = self.root / "private-root-marker"
        occupied.write_text("not a directory")
        with self.assertRaises(ConfigurationError) as caught:
            BookmarkService(occupied)
        self.assertNotIn("private-root-marker", str(caught.exception))
        self.database.write_text("not a SQLite database: private-content-marker")
        with self.assertRaises(StorageError) as caught:
            BookmarkService(self.root)
        self.assertEqual(caught.exception.code, "storage_error")
        self.assertNotIn("private-content-marker", str(caught.exception))
        self.assertNotIn(str(self.database), str(caught.exception))

    def test_fts_tracks_committed_storage_edits_and_deletes(self):
        service = BookmarkService(self.root)
        item = service.save_link("https://example.org/index", "Originalneedle")
        with closing(sqlite3.connect(self.database)) as connection, connection:
            connection.execute("UPDATE items SET title = ? WHERE id = ?", ("Updatedneedle", item["id"]))
        self.assertEqual(service.search("Originalneedle")["total"], 0)
        self.assertEqual(service.search("Updatedneedle")["items"][0]["id"], item["id"])
        with closing(sqlite3.connect(self.database)) as connection, connection:
            connection.execute("DELETE FROM items WHERE id = ?", (item["id"],))
        self.assertEqual(service.search("Updatedneedle")["total"], 0)
        self.assertEqual(service.search("")["total"], 0)

    def test_failed_save_is_atomic_and_does_not_poison_next_transaction(self):
        service = BookmarkService(self.root)
        with closing(sqlite3.connect(self.database)) as connection, connection:
            connection.execute("""
                CREATE TRIGGER reject_save AFTER INSERT ON items
                WHEN new.title = 'Reject'
                BEGIN SELECT RAISE(ABORT, 'private-sql-marker'); END
            """)
        with self.assertRaises(StorageError) as caught:
            service.save_link("https://example.org/atomic", "Reject")
        self.assertNotIn("private-sql-marker", str(caught.exception))
        self.assertEqual(service.search("")["total"], 0)
        self.assertEqual(service.search("Reject")["total"], 0)
        item = service.save_link("https://example.org/atomic", "Accepted")
        self.assertEqual(service.search("Accepted")["items"], [item])

    def test_two_concurrent_processes_initialize_and_save_one_durable_record(self):
        context = multiprocessing.get_context("spawn")
        barrier = context.Barrier(2)
        results = context.Queue()
        processes = [
            context.Process(target=_concurrent_save, args=(str(self.root), title, barrier, results))
            for title in ("First candidate", "Second candidate")
        ]
        try:
            for process in processes:
                process.start()
            responses = [results.get(timeout=30) for _ in processes]
            for process in processes:
                process.join(timeout=15)
                self.assertEqual(process.exitcode, 0)
            self.assertEqual([response[0] for response in responses], ["ok", "ok"], responses)
            first, second = [response[1] for response in responses]
            self.assertEqual(first, second)
            self.assertIn(first["title"], ("First candidate", "Second candidate"))
            service = BookmarkService(self.root)
            self.assertEqual(service.get(first["id"]), first)
            self.assertEqual(service.search("")["items"], [first])
            self.assertEqual(service.search("candidate")["total"], 1)
        finally:
            for process in processes:
                if process.is_alive():
                    process.terminate()
                if process.pid is not None:
                    process.join(timeout=5)
                    process.close()
            results.close()
            results.join_thread()
